// Package sqlite opens the platform's database (<data>/academy.db): WAL, foreign keys, the embedded goose
// migrations applied at start. Queries are generated by sqlc from queries.sql (*.gen.go).
package sqlite

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"time"

	"github.com/pressly/goose/v3"
	"modernc.org/sqlite" // database/sql driver "sqlite" (pure Go, no cgo)
	sqlite3 "modernc.org/sqlite/lib"

	"github.com/IhebBelhadj/opsforge-academy/academy/internal/platform"
	"github.com/IhebBelhadj/opsforge-academy/academy/migrations"
)

const pragmas = "_pragma=foreign_keys(1)&_pragma=journal_mode(WAL)&_pragma=busy_timeout(5000)"

// Store is the open database with its generated queries.
type Store struct {
	DB      *sql.DB
	Queries *Queries
	goose   *goose.Provider
}

// Open creates the database (and its folder) if needed, applies pending migrations and records the instance.
func Open(ctx context.Context, path string, clock platform.Clock) (*Store, error) {
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return nil, fmt.Errorf("database folder: %w", err)
	}
	db, err := sql.Open("sqlite", "file:"+path+"?"+pragmas)
	if err != nil {
		return nil, fmt.Errorf("open %s: %w", path, err)
	}
	store, err := setup(ctx, db, clock)
	if err != nil {
		_ = db.Close()
		return nil, fmt.Errorf("database %s: %w", path, err)
	}
	return store, nil
}

func setup(ctx context.Context, db *sql.DB, clock platform.Clock) (*Store, error) {
	provider, err := goose.NewProvider(goose.DialectSQLite3, db, migrations.FS)
	if err != nil {
		return nil, fmt.Errorf("migrations: %w", err)
	}
	if _, err := provider.Up(ctx); err != nil {
		return nil, fmt.Errorf("migrate: %w", err)
	}
	queries := New(db)
	if err := queries.InitInstance(ctx, clock.Now().UTC().Format(time.RFC3339)); err != nil {
		return nil, fmt.Errorf("instance: %w", err)
	}
	return &Store{DB: db, Queries: queries, goose: provider}, nil
}

// Ready reports whether the database answers and has every migration applied (readyz).
func (s *Store) Ready(ctx context.Context) error {
	if err := s.DB.PingContext(ctx); err != nil {
		return err
	}
	pending, err := s.goose.HasPending(ctx)
	if err != nil {
		return err
	}
	if pending {
		return errors.New("migrations pending")
	}
	return nil
}

// Close checkpoints the WAL into the database file and closes it.
func (s *Store) Close() error {
	_, err := s.DB.ExecContext(context.Background(), "PRAGMA wal_checkpoint(TRUNCATE)")
	return errors.Join(err, s.DB.Close())
}

// TimeLayout is how timestamps are stored: UTC, fixed width (nanoseconds always written), so text order is time
// order and queries can compare them.
const TimeLayout = "2006-01-02T15:04:05.000000000Z"

// FormatTime is t as stored.
func FormatTime(t time.Time) string { return t.UTC().Format(TimeLayout) }

// ParseTime reads a stored timestamp.
func ParseTime(s string) (time.Time, error) { return time.Parse(TimeLayout, s) }

// IsUniqueViolation reports whether err is a UNIQUE constraint failing (a row a unique index refuses).
func IsUniqueViolation(err error) bool {
	var e *sqlite.Error
	return errors.As(err, &e) && e.Code() == sqlite3.SQLITE_CONSTRAINT_UNIQUE
}
